import { ark, type HTMLArkProps } from '@ark-ui/solid/factory';
import {
  TreeView as TreeViewPrimitive,
  createFileTreeCollection,
  createTreeCollection,
  type TreeNode,
  type TreeViewLoadChildrenDetails,
  type TreeViewNodeProviderProps,
  type TreeViewNodeState,
  type TreeViewRootComponent,
  type TreeViewRootProps,
  type TreeViewRootProviderComponent,
  type TreeViewRootProviderProps,
  useTreeView,
  useTreeViewContext,
  useTreeViewNodeContext,
} from '@ark-ui/solid/tree-view';
import { clsx } from 'clsx';
import type { Accessor, ComponentProps, JSX } from 'solid-js';
import { children, splitProps } from 'solid-js';
import { CheckIcon, ChevronRightIcon, IndeterminateIcon } from '@/lib/moduix/icons/ui/Icons';
import styles from './TreeView.module.css';

const TreeViewRoot = function TreeViewRoot<T extends TreeNode>(props: TreeViewRootProps<T>) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);

  return (
    <TreeViewPrimitive.Root
      asChild={local.asChild}
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="tree-view-root"
    >
      {local.children}
    </TreeViewPrimitive.Root>
  );
} as TreeViewRootComponent;

const TreeViewRootProvider = function TreeViewRootProvider<T extends TreeNode>(
  props: TreeViewRootProviderProps<T>,
) {
  const [local, others] = splitProps(props, ['asChild', 'children', 'class']);

  return (
    <TreeViewPrimitive.RootProvider
      asChild={local.asChild}
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="tree-view-root-provider"
    >
      {local.children}
    </TreeViewPrimitive.RootProvider>
  );
} as TreeViewRootProviderComponent;

function TreeViewLabel(props: ComponentProps<typeof TreeViewPrimitive.Label>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TreeViewPrimitive.Label
      class={clsx(styles.label, local.class)}
      {...others}
      data-slot="tree-view-label"
    />
  );
}

function TreeViewTree(props: ComponentProps<typeof TreeViewPrimitive.Tree>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TreeViewPrimitive.Tree
      class={clsx(styles.tree, local.class)}
      {...others}
      data-slot="tree-view-tree"
    />
  );
}

function TreeViewBranch(props: ComponentProps<typeof TreeViewPrimitive.Branch>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TreeViewPrimitive.Branch
      class={clsx(styles.branch, local.class)}
      {...others}
      data-slot="tree-view-branch"
    />
  );
}

function TreeViewBranchControl(props: ComponentProps<typeof TreeViewPrimitive.BranchControl>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TreeViewPrimitive.BranchControl
      class={clsx(styles.branchControl, local.class)}
      {...others}
      data-slot="tree-view-branch-control"
    />
  );
}

function TreeViewBranchTrigger(props: ComponentProps<typeof TreeViewPrimitive.BranchTrigger>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <TreeViewPrimitive.BranchTrigger
      class={clsx(styles.branchTrigger, local.class)}
      {...others}
      data-slot="tree-view-branch-trigger"
    >
      {resolvedChildren() ?? <ChevronRightIcon />}
    </TreeViewPrimitive.BranchTrigger>
  );
}

function TreeViewBranchIndicator(props: ComponentProps<typeof TreeViewPrimitive.BranchIndicator>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <TreeViewPrimitive.BranchIndicator
      class={clsx(styles.branchIndicator, local.class)}
      {...others}
      data-slot="tree-view-branch-indicator"
    >
      {resolvedChildren() ?? <ChevronRightIcon />}
    </TreeViewPrimitive.BranchIndicator>
  );
}

function TreeViewBranchText(props: ComponentProps<typeof TreeViewPrimitive.BranchText>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TreeViewPrimitive.BranchText
      class={clsx(styles.branchText, local.class)}
      {...others}
      data-slot="tree-view-branch-text"
    />
  );
}

function TreeViewBranchContent(props: ComponentProps<typeof TreeViewPrimitive.BranchContent>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TreeViewPrimitive.BranchContent
      class={clsx(styles.branchContent, local.class)}
      {...others}
      data-slot="tree-view-branch-content"
    />
  );
}

function TreeViewBranchIndentGuide(
  props: ComponentProps<typeof TreeViewPrimitive.BranchIndentGuide>,
) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TreeViewPrimitive.BranchIndentGuide
      class={clsx(styles.branchIndentGuide, local.class)}
      {...others}
      data-slot="tree-view-branch-indent-guide"
    />
  );
}

function TreeViewItem(props: ComponentProps<typeof TreeViewPrimitive.Item>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TreeViewPrimitive.Item
      class={clsx(styles.item, local.class)}
      {...others}
      data-slot="tree-view-item"
    />
  );
}

function TreeViewItemText(props: ComponentProps<typeof TreeViewPrimitive.ItemText>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TreeViewPrimitive.ItemText
      class={clsx(styles.itemText, local.class)}
      {...others}
      data-slot="tree-view-item-text"
    />
  );
}

function TreeViewItemIndicator(props: ComponentProps<typeof TreeViewPrimitive.ItemIndicator>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <TreeViewPrimitive.ItemIndicator
      class={clsx(styles.itemIndicator, local.class)}
      {...others}
      data-slot="tree-view-item-indicator"
    >
      {resolvedChildren() ?? <CheckIcon />}
    </TreeViewPrimitive.ItemIndicator>
  );
}

function TreeViewNodeCheckbox(props: ComponentProps<typeof TreeViewPrimitive.NodeCheckbox>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TreeViewPrimitive.NodeCheckbox
      class={clsx(styles.nodeCheckbox, local.class)}
      {...others}
      data-slot="tree-view-node-checkbox"
    />
  );
}

type TreeViewNodeCheckboxIndicatorProps = ComponentProps<
  typeof TreeViewPrimitive.NodeCheckboxIndicator
> &
  Omit<HTMLArkProps<'span'>, 'children'>;

function TreeViewNodeCheckboxIndicator(props: TreeViewNodeCheckboxIndicatorProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'children',
    'class',
    'fallback',
    'indeterminate',
  ]);
  const resolvedChildren = children(() => local.children);

  return (
    <ark.span
      asChild={local.asChild}
      class={clsx(styles.nodeCheckboxIndicator, local.class)}
      {...others}
      data-slot="tree-view-node-checkbox-indicator"
    >
      <TreeViewPrimitive.NodeCheckboxIndicator
        fallback={local.fallback}
        indeterminate={local.indeterminate ?? <IndeterminateIcon />}
      >
        {resolvedChildren() ?? <CheckIcon />}
      </TreeViewPrimitive.NodeCheckboxIndicator>
    </ark.span>
  );
}

function TreeViewNodeRenameInput(props: ComponentProps<typeof TreeViewPrimitive.NodeRenameInput>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <TreeViewPrimitive.NodeRenameInput
      class={clsx(styles.nodeRenameInput, local.class)}
      {...others}
      data-slot="tree-view-node-rename-input"
    />
  );
}

const TreeViewNodeProvider = TreeViewPrimitive.NodeProvider;

type TreeViewNodeRenderProps<T extends TreeNode> = {
  indexPath: number[];
  node: T;
  state: Accessor<TreeViewNodeState>;
};

type TreeViewNodeProps<T extends TreeNode> = {
  children: (props: TreeViewNodeRenderProps<T>) => JSX.Element;
  indexPath: number[];
  node: T;
};

function TreeViewNodeContent<T extends TreeNode>(props: TreeViewNodeProps<T>) {
  return props.children({
    indexPath: props.indexPath,
    node: props.node,
    state: useTreeViewNodeContext(),
  });
}

function TreeViewNode<T extends TreeNode>(props: TreeViewNodeProps<T>) {
  return (
    <TreeViewNodeProvider node={props.node} indexPath={props.indexPath}>
      <TreeViewNodeContent {...props} />
    </TreeViewNodeProvider>
  );
}

type TreeViewComponent = typeof TreeViewRoot & {
  Root: typeof TreeViewRoot;
  RootProvider: typeof TreeViewRootProvider;
  Context: typeof TreeViewPrimitive.Context;
  NodeContext: typeof TreeViewPrimitive.NodeContext;
  Label: typeof TreeViewLabel;
  Tree: typeof TreeViewTree;
  Node: typeof TreeViewNode;
  NodeProvider: typeof TreeViewNodeProvider;
  Branch: typeof TreeViewBranch;
  BranchControl: typeof TreeViewBranchControl;
  BranchTrigger: typeof TreeViewBranchTrigger;
  BranchIndicator: typeof TreeViewBranchIndicator;
  BranchText: typeof TreeViewBranchText;
  BranchContent: typeof TreeViewBranchContent;
  BranchIndentGuide: typeof TreeViewBranchIndentGuide;
  Item: typeof TreeViewItem;
  ItemText: typeof TreeViewItemText;
  ItemIndicator: typeof TreeViewItemIndicator;
  NodeCheckbox: typeof TreeViewNodeCheckbox;
  NodeCheckboxIndicator: typeof TreeViewNodeCheckboxIndicator;
  NodeRenameInput: typeof TreeViewNodeRenameInput;
};

const TreeView: TreeViewComponent = Object.assign(TreeViewRoot, {
  Root: TreeViewRoot,
  RootProvider: TreeViewRootProvider,
  Context: TreeViewPrimitive.Context,
  NodeContext: TreeViewPrimitive.NodeContext,
  Label: TreeViewLabel,
  Tree: TreeViewTree,
  Node: TreeViewNode,
  NodeProvider: TreeViewNodeProvider,
  Branch: TreeViewBranch,
  BranchControl: TreeViewBranchControl,
  BranchTrigger: TreeViewBranchTrigger,
  BranchIndicator: TreeViewBranchIndicator,
  BranchText: TreeViewBranchText,
  BranchContent: TreeViewBranchContent,
  BranchIndentGuide: TreeViewBranchIndentGuide,
  Item: TreeViewItem,
  ItemText: TreeViewItemText,
  ItemIndicator: TreeViewItemIndicator,
  NodeCheckbox: TreeViewNodeCheckbox,
  NodeCheckboxIndicator: TreeViewNodeCheckboxIndicator,
  NodeRenameInput: TreeViewNodeRenameInput,
});

export {
  TreeView,
  createFileTreeCollection,
  createTreeCollection,
  useTreeView,
  useTreeViewContext,
  useTreeViewNodeContext,
  type TreeViewLoadChildrenDetails,
  type TreeViewNodeProps,
  type TreeViewNodeRenderProps,
  type TreeViewNodeState,
  type TreeViewNodeProviderProps,
};

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: flex;
    width: var(--moduix-tree-view-width, 20rem);
    max-width: var(--moduix-tree-view-max-width, 100%);
    min-width: 0;
    flex-direction: column;
    gap: var(--moduix-tree-view-root-gap, var(--moduix-spacing-2));
    color: var(--moduix-tree-view-color, var(--moduix-color-foreground));

    &[data-disabled] {
      opacity: var(--moduix-tree-view-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }

  .label {
    color: var(
      --moduix-tree-view-label-color,
      var(--moduix-tree-view-color, var(--moduix-color-foreground))
    );
    font-size: var(--moduix-tree-view-label-font-size, var(--moduix-text-sm));
    font-weight: var(--moduix-tree-view-label-font-weight, var(--moduix-weight-medium));
    line-height: var(--moduix-tree-view-label-line-height, var(--moduix-line-height-text-sm));
    user-select: none;
  }

  .tree {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: var(--moduix-tree-view-row-gap, var(--moduix-spacing-1));
    color: var(--moduix-tree-view-color, var(--moduix-color-foreground));
    font-size: var(--moduix-tree-view-item-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-tree-view-item-line-height, var(--moduix-line-height-text-sm));
  }

  .branch {
    position: relative;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: var(--moduix-tree-view-row-gap, var(--moduix-spacing-1));
  }

  .branchControl,
  .item {
    position: relative;
    z-index: 0;
    box-sizing: border-box;
    display: flex;
    width: 100%;
    min-width: 0;
    min-height: var(--moduix-tree-view-item-min-height, var(--moduix-size-sm));
    align-items: center;
    gap: var(--moduix-tree-view-item-gap, var(--moduix-spacing-2));
    border: var(--moduix-tree-view-item-border-width, 0) solid
      var(--moduix-tree-view-item-border-color, transparent);
    border-radius: var(--moduix-tree-view-item-radius, var(--moduix-radius-sm));
    outline: none;
    padding-block: var(--moduix-tree-view-item-padding-y, var(--moduix-spacing-1));
    padding-inline-end: var(--moduix-tree-view-item-padding-x, var(--moduix-spacing-2));
    padding-inline-start: calc(
      var(--moduix-tree-view-item-padding-x, var(--moduix-spacing-2)) +
        ((var(--depth, 1) - 1) * var(--moduix-tree-view-indent, 1rem))
    );
    color: var(
      --moduix-tree-view-item-color,
      var(--moduix-tree-view-color, var(--moduix-color-foreground))
    );
    cursor: pointer;
    font: inherit;
    text-align: start;
    text-decoration: none;
    transition:
      color var(--moduix-tree-view-transition, var(--moduix-transition-default)),
      opacity var(--moduix-tree-view-transition, var(--moduix-transition-default));
    user-select: none;

    &::before {
      position: absolute;
      z-index: -1;
      inset-block: 0;
      inset-inline-end: 0;
      inset-inline-start: calc(
        var(--moduix-tree-view-item-padding-x, var(--moduix-spacing-2)) +
          ((var(--depth, 1) - 1) * var(--moduix-tree-view-indent, 1rem))
      );
      border-radius: inherit;
      background-color: var(--moduix-tree-view-item-bg, transparent);
      content: '';
      box-shadow: inset 0 0 0
        var(
          --moduix-tree-view-focus-ring-width,
          var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        )
        transparent;
      pointer-events: none;
      transition:
        background-color var(--moduix-tree-view-transition, var(--moduix-transition-default)),
        box-shadow var(--moduix-tree-view-transition, var(--moduix-transition-default));
    }

    @media (hover: hover) {
      &:not([data-disabled]):hover {
        color: var(--moduix-tree-view-item-hover-color, var(--moduix-color-accent-foreground));

        &::before {
          background-color: var(--moduix-tree-view-item-hover-bg, var(--moduix-color-accent));
        }
      }
    }

    &:focus-visible,
    &[data-focus] {
      &::before {
        box-shadow: inset 0 0 0
          var(
            --moduix-tree-view-focus-ring-width,
            var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
          )
          var(--moduix-tree-view-focus-ring-color, var(--moduix-color-ring));
      }
    }

    &[data-selected] {
      color: var(--moduix-tree-view-item-selected-color, var(--moduix-color-accent-foreground));

      &::before {
        background-color: var(--moduix-tree-view-item-selected-bg, var(--moduix-color-accent));
      }
    }

    &[data-disabled] {
      color: var(--moduix-tree-view-item-disabled-color, var(--moduix-color-muted-foreground));
      cursor: default;
      opacity: var(--moduix-tree-view-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }

  .item {
    padding-inline-start: calc(
      var(--moduix-tree-view-item-padding-x, var(--moduix-spacing-2)) + var(--moduix-spacing-1) +
        var(--moduix-spacing-1) + ((var(--depth, 1) - 1) * var(--moduix-tree-view-indent, 1rem))
    );
  }

  .branchTrigger,
  .branchIndicator,
  .itemIndicator {
    display: inline-flex;
    width: var(--moduix-tree-view-indicator-size, var(--moduix-spacing-4));
    height: var(--moduix-tree-view-indicator-size, var(--moduix-spacing-4));
    flex: 0 0 var(--moduix-tree-view-indicator-size, var(--moduix-spacing-4));
    align-items: center;
    justify-content: center;
    color: var(--moduix-tree-view-indicator-color, currentColor);

    & svg {
      width: var(--moduix-tree-view-indicator-icon-size, var(--moduix-spacing-3-5));
      height: var(--moduix-tree-view-indicator-icon-size, var(--moduix-spacing-3-5));
    }
  }

  .branchTrigger,
  .branchIndicator {
    transition: transform var(--moduix-tree-view-transition, var(--moduix-transition-default));

    &[data-state='open'] {
      transform: rotate(90deg);
    }
  }

  .branchText,
  .itemText {
    display: inline-flex;
    min-width: 0;
    flex: 1;
    align-items: center;
    gap: var(--moduix-tree-view-item-text-gap, var(--moduix-spacing-2));
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;

    & svg {
      width: var(--moduix-tree-view-node-icon-size, var(--moduix-spacing-4));
      height: var(--moduix-tree-view-node-icon-size, var(--moduix-spacing-4));
      flex: 0 0 var(--moduix-tree-view-node-icon-size, var(--moduix-spacing-4));
    }
  }

  .branchContent {
    position: relative;
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: var(--moduix-tree-view-row-gap, var(--moduix-spacing-1));
    overflow: hidden;

    &[data-state='open'] {
      animation:
        tree-view-slide-down var(--moduix-tree-view-content-transition-duration, 150ms) ease-out,
        tree-view-fade-in var(--moduix-tree-view-content-transition-duration, 150ms) ease-out;
    }

    &[data-state='closed'] {
      animation:
        tree-view-slide-up var(--moduix-tree-view-content-transition-duration, 150ms) ease-out,
        tree-view-fade-out var(--moduix-tree-view-content-transition-duration, 150ms) ease-out;
    }

    @media (prefers-reduced-motion: reduce) {
      animation: none;
    }
  }

  .branchIndentGuide {
    position: absolute;
    z-index: 1;
    top: 0;
    bottom: 0;
    width: var(--moduix-tree-view-indent-guide-width, var(--moduix-border-width-sm));
    background-color: var(--moduix-tree-view-indent-guide-color, var(--moduix-color-border));
    pointer-events: none;
    inset-inline-start: calc(
      var(--moduix-tree-view-item-padding-x, var(--moduix-spacing-2)) +
        ((var(--depth, 1) - 1) * var(--moduix-tree-view-indent, 1rem)) +
        (var(--moduix-tree-view-indicator-size, var(--moduix-spacing-4)) / 2)
    );
  }

  .nodeCheckbox {
    box-sizing: border-box;
    display: inline-flex;
    width: var(--moduix-tree-view-checkbox-size, var(--moduix-spacing-4));
    height: var(--moduix-tree-view-checkbox-size, var(--moduix-spacing-4));
    flex: 0 0 var(--moduix-tree-view-checkbox-size, var(--moduix-spacing-4));
    align-items: center;
    justify-content: center;
    border: var(--moduix-tree-view-checkbox-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-tree-view-checkbox-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-tree-view-checkbox-radius, var(--moduix-radius-xs));
    background-color: var(--moduix-tree-view-checkbox-bg, var(--moduix-color-background));
    color: var(--moduix-tree-view-checkbox-color, var(--moduix-color-primary-foreground));
    outline: var(
        --moduix-tree-view-focus-ring-width,
        var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
      )
      solid transparent;
    outline-offset: var(
      --moduix-tree-view-checkbox-focus-ring-offset,
      var(--moduix-border-width-sm)
    );
    transition:
      background-color var(--moduix-tree-view-transition, var(--moduix-transition-default)),
      border-color var(--moduix-tree-view-transition, var(--moduix-transition-default)),
      outline-color var(--moduix-tree-view-transition, var(--moduix-transition-default));

    &[data-state='checked'],
    &[data-state='indeterminate'] {
      border-color: var(--moduix-tree-view-checkbox-checked-bg, var(--moduix-color-primary));
      background-color: var(--moduix-tree-view-checkbox-checked-bg, var(--moduix-color-primary));
    }

    &:focus-visible {
      outline-color: var(--moduix-tree-view-focus-ring-color, var(--moduix-color-ring));
    }

    &[data-disabled] {
      cursor: default;
      opacity: var(--moduix-tree-view-disabled-opacity, var(--moduix-opacity-disabled));
    }

    & svg {
      width: var(--moduix-tree-view-checkbox-icon-size, var(--moduix-spacing-3));
      height: var(--moduix-tree-view-checkbox-icon-size, var(--moduix-spacing-3));
    }
  }

  .nodeCheckboxIndicator {
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .nodeRenameInput {
    box-sizing: border-box;
    min-width: 0;
    flex: 1;
    border: var(--moduix-tree-view-rename-input-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-tree-view-rename-input-border-color, var(--moduix-color-ring));
    border-radius: var(--moduix-tree-view-rename-input-radius, var(--moduix-radius-xs));
    padding-block: var(--moduix-tree-view-rename-input-padding-y, 0);
    padding-inline: var(--moduix-tree-view-rename-input-padding-x, var(--moduix-spacing-1));
    background-color: var(--moduix-tree-view-rename-input-bg, var(--moduix-color-background));
    color: var(--moduix-tree-view-rename-input-color, var(--moduix-color-foreground));
    font: inherit;
    outline: var(
        --moduix-tree-view-focus-ring-width,
        var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
      )
      solid transparent;
    outline-offset: calc(
      var(
          --moduix-tree-view-focus-ring-width,
          var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        ) *
        -1
    );

    &:focus-visible {
      outline-color: var(--moduix-tree-view-focus-ring-color, var(--moduix-color-ring));
    }
  }

  @keyframes tree-view-slide-down {
    from {
      height: 0;
    }

    to {
      height: var(--height);
    }
  }

  @keyframes tree-view-slide-up {
    from {
      height: var(--height);
    }

    to {
      height: 0;
    }
  }

  @keyframes tree-view-fade-in {
    from {
      opacity: 0.01;
    }

    to {
      opacity: 1;
    }
  }

  @keyframes tree-view-fade-out {
    from {
      opacity: 1;
    }

    to {
      opacity: 0.01;
    }
  }
}
